import {SoftwareScene} from './software-scene.js?v=29';
import {LabScene} from './scene3d.js?v=29';
import {initialState} from './experiments.js?v=17';
import {evaluate,duration} from './models.js?v=17';
const cache=new Map();let renderer=null,queue=[],busy=false,token=0,observer=null,softwareOnly=false;
export function stopThumbnails(){token++;queue=[];observer?.disconnect();}
export function observeThumbnails(experiments){stopThumbnails();const own=token;const targets=document.querySelectorAll('[data-thumb]');for(const el of targets){const image=cache.get(el.dataset.thumb);if(image){el.innerHTML=`<img src="${image}" alt="" loading="lazy">`;el.dataset.ready='true';}}
 if(!('IntersectionObserver'in globalThis)){for(const el of targets)if(!el.dataset.ready)queue.push({el,own});pump(experiments);return;}
 observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting&&!e.target.dataset.ready){queue.push({el:e.target,own});observer.unobserve(e.target);}pump(experiments);},{rootMargin:'150px'});targets.forEach(el=>{if(!el.dataset.ready)observer.observe(el)});}
function pump(experiments){if(busy||!queue.length)return;busy=true;setTimeout(()=>{const job=queue.shift();if(job&&job.own===token&&job.el.isConnected){try{if(!renderer){if(!softwareOnly){try{renderer=new LabScene();}catch{softwareOnly=true;}}if(!renderer)renderer=new SoftwareScene();}renderer.renderer.setPixelRatio(1);renderer.renderer.shadowMap.enabled=false;renderer.renderer.setSize(380,250,false);renderer.camera.aspect=380/250;renderer.camera.updateProjectionMatrix();const e=experiments.find(e=>e.id===job.el.dataset.thumb),s={...initialState(e),t:0},cfg={mode:3,capMode:'charge',thumbnail:true,switches:{lines:true,connections:true,components:true,resultant:true,parallelogram:true,axes:false,vectors:true,trajectory:true}};let d=evaluate(e.id,s,cfg);if(e.params.some(p=>p.key==='t'))s.t=Math.min(duration(e,s,d)*.3,1.5);d=evaluate(e.id,s,cfg);renderer.update(e.id,s,d,cfg);renderer.view('iso');const url=renderer.capture();cache.set(e.id,url);if(cache.size>48)cache.delete(cache.keys().next().value);job.el.innerHTML=`<img src="${url}" alt="" loading="lazy">`;job.el.dataset.ready='true';}catch{renderer?.dispose();renderer=null;if(!softwareOnly){softwareOnly=true;queue.unshift({...job,retry:true});}else{job.el.setAttribute('aria-label',job.el.getAttribute('aria-label')+' · mở bài để xem mô hình');job.el.dataset.ready='true';}}}busy=false;pump(experiments);},24);}
